// The loader's rules from the agentskills.io specification atoma v0.5.0 validates
// against: a skill is a directory holding SKILL.md, the walk stops there, and the
// frontmatter name must equal that directory's name.
import { readFileSync, readdirSync } from "node:fs";
import { basename, join } from "node:path";

const root = process.argv[2]!;
const NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const found: string[] = [];
const problems: string[] = [];

const walk = (dir: string): void => {
  if (readdirSync(dir, { withFileTypes: true }).some((e) => e.isFile() && e.name === "SKILL.md")) {
    const file = join(dir, "SKILL.md");
    const raw = readFileSync(file, "utf8");
    const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]+)$/);
    if (!match) { problems.push(`${file}: no frontmatter or no body`); return; }
    const meta = Bun.YAML.parse(match[1]!) as { name?: string; description?: string };
    const leaf = basename(dir);
    if (!meta.name) problems.push(`${file}: no name`);
    else if (meta.name !== leaf) problems.push(`${file}: name "${meta.name}" != directory "${leaf}"`);
    else if (!NAME.test(meta.name) || meta.name.length > 64) problems.push(`${file}: name "${meta.name}" fails the format`);
    if (!meta.description || meta.description.length > 1024) problems.push(`${file}: description missing or over 1024`);
    found.push(meta.name ?? "?");
    return; // the loader stops descending here
  }
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) walk(join(dir, entry.name));
  }
};
walk(root);
console.log(JSON.stringify({ count: found.length, names: found.sort(), problems }, null, 2));
